 * The organization's monthly period: whether its subscription is live, when the billing period
 * began (null without a live one that has begun), and when the current month of it began. A
 * yearly plan still renews monthly, on the day its period began; without a live subscription the
 * month is the calendar month in UTC. The computer allowance and the cache share on Usage both
 * count from here.
 */
export function monthlyBillingPeriod(
  billing:
    | {
        status: string | null;
        currentPeriodStartsAt: Date | null;
        byokInterval: string | null;
      }
    | null
    | undefined,
  now: Date,
): { live: boolean; periodStart: Date | null; since: Date } {
  const live = Boolean(billing?.status && LIVE_SUBSCRIPTION_STATUSES.has(billing.status));
  const periodStart =
    live && billing?.currentPeriodStartsAt && billing.currentPeriodStartsAt <= now
      ? billing.currentPeriodStartsAt
      : null;
  const since = periodStart
    ? // A yearly plan's allowance still renews monthly, on the day its period began.
      billing?.byokInterval === "year"
      ? latestMonthlyAnniversary(periodStart, now)
      : periodStart
    : new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
  return { live, periodStart, since };
}

