/// The plugin catalog last read from the public registries, served at once after a restart and
/// refreshed in the background. `refreshedAt` is the last time every registry answered;
/// `failures` counts incomplete refreshes in a row and `retryAt` is when any process may try again.
model DozoCatalogSnapshot {
  key         String    @id
  data        Json
  refreshedAt DateTime
  failures    Int       @default(0)
  retryAt     DateTime?

  @@map("dozo_catalog_snapshots")
}

/// A catalog logo or site icon, drawn small once and served from our own domain under its hash.
/// `source` is the logo's address or `site:<origin>`; a null hash records a source with no image.
model DozoCatalogImage {
  source    String   @id
  hash      String?
  body      Bytes?
  checkedAt DateTime

  @@index([hash])
  @@map("dozo_catalog_images")
}

